-- @set: request.jwt.claims={"sub":"1","role":"authenticated","aud":"authenticated","pad":""}
-- Fix: scalar subquery => InitPlan, parsed once per statement.
alter table app.documents enable row level security;
create policy p on app.documents for select to bench_user
  using (owner_id = (select (current_setting('request.jwt.claims', true)::jsonb ->> 'sub')::int));
